const ANVISA_TIPO_LABELS={cnpj:"CNPJ",nome:"Nome/marca",registro:"Nº de registro",processo:"Nº de processo"};function initAnvisaSection(){const t=document.getElementById("anvisaSearchForm");t&&t.addEventListener("submit",handleAnvisaSearchSubmit)}function yalcaEscapeHtmlAnvisa(t){const e=document.createElement("div");return e.textContent=t??"",e.innerHTML}async function handleAnvisaSearchSubmit(t){t.preventDefault();const e=document.getElementById("anvisaCategoria").value,a=document.getElementById("anvisaTipo").value,n=document.getElementById("anvisaValor").value.trim(),s=document.getElementById("anvisaSearchStatus"),o=document.getElementById("anvisaResultPanel"),i=t.target.querySelector('button[type="submit"]');if(!n)return s.textContent="Digite um valor para pesquisar.",void(s.style.color="var(--critical)");s.textContent="",o.style.display="none",i.disabled=!0,i.textContent="Pesquisando...";try{const t=await yalcaAnvisaSearch(e,a,n);if(!t.ok)return s.textContent=t.message||"Não foi possível pesquisar agora.",void(s.style.color="var(--warning)");renderAnvisaResults(t.results||[],t.source)}catch(t){s.textContent="Não foi possível consultar agora: "+t.message,s.style.color="var(--critical)"}finally{i.disabled=!1,i.textContent="Pesquisar"}}function renderAnvisaResults(t,e){const a=document.getElementById("anvisaResultPanel"),n=document.getElementById("anvisaResultBody"),s=document.getElementById("anvisaResultCount"),o=document.getElementById("anvisaSearchStatus");if(0===t.length)return o.textContent="Nenhum produto encontrado para essa busca.",o.style.color="var(--text-muted)",void(a.style.display="none");s.textContent=`${t.length} produto${1===t.length?"":"s"} encontrado${1===t.length?"":"s"}${"cache"===e?" (resultado em cache)":""}`,n.innerHTML=t.map(t=>{const e="Ativo"===t.situacaoRegistro?"ativo":"pausado";return`\n      <tr>\n        <td data-label="Produto">\n          <strong>${yalcaEscapeHtmlAnvisa(t.descricaoProduto||"—")}</strong>\n          <div class="kpi-card__hint">Nº ${yalcaEscapeHtmlAnvisa(t.numeroRegistroOuNotificacao||"—")} · ${yalcaEscapeHtmlAnvisa(t.tipoRegularizacao||"—")}</div>\n        </td>\n        <td data-label="Empresa">${yalcaEscapeHtmlAnvisa(t.razaoSocialDetentor||"—")}<div class="kpi-card__hint">${yalcaEscapeHtmlAnvisa(t.cnpjDetentorFormatado||"—")}</div></td>\n        <td data-label="Situação"><span class="badge badge--${e}">${yalcaEscapeHtmlAnvisa(t.situacaoRegistro||"—")}</span></td>\n        <td data-label="Vencimento">${yalcaEscapeHtmlAnvisa(t.vencimento||"—")}</td>\n        <td data-label="Processo">${yalcaEscapeHtmlAnvisa(t.numeroProcesso||"—")}</td>\n      </tr>`}).join(""),a.style.display="",document.getElementById("anvisaSearchStatus").textContent=""}